const body = $json.body || $json;
const action = String(body.action || '').trim();
const cursoId = String(body.curso_id || '');
const institucionId = String(body.institucion_id || '');
if (!/^[1-9][0-9]*$/.test(cursoId) || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/.test(institucionId)) throw new Error('curso_id e institucion_id inválidos.');
if (!['delete_document', 'clear_course'].includes(action)) throw new Error('Acción de conocimiento no válida.');
const archivo = action === 'delete_document' ? String(body.archivo || '').trim() : null;
if (action === 'delete_document' && !archivo) throw new Error('archivo es obligatorio para delete_document.');
return [{ json: { action, archivo, namespace: `inst_${institucionId}_curso_${cursoId}` } }];

const request = $('Validar acción del agente').first().json;
const result = $input.first().json;
const alreadyEmpty = result.statusCode === 404 && result.body?.code === 5 && result.body?.message === 'Namespace not found';
if (!(result.statusCode >= 200 && result.statusCode < 300) && !alreadyEmpty) {
  throw new Error('Pinecone no confirmó la limpieza (HTTP ' + result.statusCode + ').');
}
return [{ json: { success: true, action: request.action, namespace: request.namespace, archivo: request.archivo, already_empty: alreadyEmpty } }];
